use smaul_native::data_filter::filter_record;
use smaul_native::dataset::DatasetStream;
use smaul_native::synthetic_data;
use rand::SeedableRng;
use serde_json::Value;
use std::fs::{self,File};
use std::io::{self,BufRead,BufReader,Write};
use std::path::{Path,PathBuf};
use std::process::Command;
fn val(a:&[String],name:&str,default:&str)->String{a.windows(2).find(|x|x[0]==name).map(|x|x[1].clone()).unwrap_or_else(||default.into())}
fn stream_jsonl(path:&Path,dataset:&str,min:usize,max:usize,limit:usize,mut out:impl Write)->Result<usize,String>{let r=BufReader::new(File::open(path).map_err(|e|e.to_string())?);let mut n=0;for line in r.lines(){let line=line.map_err(|e|e.to_string())?;let Ok(v)=serde_json::from_str::<Value>(&line)else{continue};if let Some(t)=filter_record(&v,dataset,min,max){writeln!(out,"{}",serde_json::json!({"text":t})).map_err(|e|e.to_string())?;n+=1;if limit>0&&n>=limit{break}}}Ok(n)}
fn filter_stdin(dataset:&str,min:usize,max:usize)->Result<(),String>{let stdin=io::stdin();let mut out=io::BufWriter::new(io::stdout());for line in stdin.lock().lines(){let line=line.map_err(|e|e.to_string())?;let Ok(v)=serde_json::from_str::<Value>(&line)else{continue};if let Some(t)=filter_record(&v,dataset,min,max){writeln!(out,"{}",serde_json::json!({"text":t})).map_err(|e|e.to_string())?}}Ok(())}
fn synthetic(count:usize,out:&Path,seed:u64)->Result<(),String>{let mut rng=rand::rngs::StdRng::seed_from_u64(seed);let mut f=io::BufWriter::new(File::create(out).map_err(|e|e.to_string())?);for _ in 0..count{serde_json::to_writer(&mut f,&synthetic_data::generate(&mut rng)).map_err(|e|e.to_string())?;f.write_all(b"\n").map_err(|e|e.to_string())?}Ok(())}
fn download(repo:&str,path:&str,out:&Path)->Result<(),String>{let api=format!("https://huggingface.co/api/datasets/{repo}/tree/main/{path}?recursive=true&expand=false&limit=1000");let body=String::from_utf8(Command::new("curl").args(["-fsSL",&api]).output().map_err(|e|e.to_string())?.stdout).map_err(|e|e.to_string())?;let items:Vec<Value>=serde_json::from_str(&body).map_err(|e|e.to_string())?;let files=items.iter().filter_map(|x|x.get("path").and_then(|v|v.as_str())).filter(|x|x.ends_with(".parquet")).collect::<Vec<_>>();if files.is_empty(){return Err(format!("no parquet files found in {repo}/{path}"))}for rel in files{let target=out.join(rel.rsplit('/').next().unwrap_or("data.parquet"));if target.exists(){continue}fs::create_dir_all(out).map_err(|e|e.to_string())?;let url=format!("https://huggingface.co/datasets/{repo}/resolve/main/{rel}");let status=Command::new("curl").args(["-fL","--retry","5","-o",target.to_str().unwrap_or("data.parquet"),&url]).status().map_err(|e|e.to_string())?;if !status.success(){return Err(format!("download failed: {rel}"))}}Ok(())}
fn stream_tokens(input:&Path,tokenizer:&Path,ctx:usize,limit:usize)->Result<(),String>{let tok=smaul_native::tokenizer::Tokenizer::from_json_file(tokenizer)?;let mut stream=DatasetStream::open(input,tok,ctx)?;let mut n=0;let mut out=io::BufWriter::new(io::stdout());while let Some(batch)=stream.next_batch()?{writeln!(out,"{}",serde_json::json!({"input":batch.input,"target":batch.target,"file":batch.position.file,"record":batch.position.record})).map_err(|e|e.to_string())?;n+=1;if limit>0&&n>=limit{break}}eprintln!("[DONE] streamed {n} token batches");Ok(())}
fn main()->Result<(),String>{let a=std::env::args().collect::<Vec<_>>();match a.get(1).map(String::as_str).unwrap_or("help"){"filter"=>filter_stdin(&val(&a,"--dataset","auto"),val(&a,"--min-chars","20").parse().unwrap(),val(&a,"--max-chars","1000000").parse().unwrap()),"stream"=>{let input=PathBuf::from(val(&a,"--input","./datasets/train.jsonl"));if a.iter().any(|x|x=="--tokenizer"){stream_tokens(&input,&PathBuf::from(val(&a,"--tokenizer","tokenizer.json")),val(&a,"--ctx-len","1024").parse().unwrap(),val(&a,"--max-batches","0").parse().unwrap())}else{let n=stream_jsonl(&input,&val(&a,"--dataset","auto"),val(&a,"--min-chars","20").parse().unwrap(),val(&a,"--max-chars","1000000").parse().unwrap(),val(&a,"--max-records","0").parse().unwrap(),io::stdout())?;eprintln!("[DONE] streamed {n} records");Ok(())}},"synthetic"=>synthetic(val(&a,"--count","1000").parse().map_err(|_|"invalid --count")?,&PathBuf::from(val(&a,"--output","synthetic.jsonl")),val(&a,"--seed","42").parse().unwrap()),"download"=>{let lang=val(&a,"--dataset","hindi");let(repo,path)=match lang.as_str(){"hindi"=>("HuggingFaceFW/fineweb-2","data/hin_Deva/train"),"english"=>("HuggingFaceFW/fineweb","data/100BT"),"openthoughts"=>("open-thoughts/OpenThoughts3-1.2M","data"),_=>return Err("dataset must be hindi, english, or openthoughts".into())};download(repo,path,&PathBuf::from(val(&a,"--output","./datasets")))},_=>{println!("smaul-dataset <filter|stream|synthetic|download> [options]");println!("stream: --input FILE [--tokenizer tokenizer.json --ctx-len N --max-batches N]");println!("filter: JSONL stdin -> filtered JSONL stdout");println!("synthetic: --count N --output FILE [--seed N]");println!("download: --dataset hindi|english|openthoughts --output DIR");Ok(())}}
}
